rules.source:
rule "mac normalize client_mac from dns_client_ip"
when
  has_field("dns_client_ip") &&
  !has_field("client_mac")
then
  let ip = to_string($message.dns_client_ip);
  let mac = to_string(lookup_value("infoblox-nios-ip-to-mac", ip));
  set_field("client_mac", mac);
end

rule "mac enrich client_mac"
when
  has_field("client_mac") &&
  to_string($message.client_mac) != ""
then
  let mac = lowercase(to_string($message.client_mac));
  let host = lookup_value("infoblox-nios-mac", mac);
  set_field("client_hostname", to_string(host));
end
